import{z as A,x as B,o as r,c as m,q as i,j as l,D as e,d as E,s as o,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"焦面倾斜与场曲补偿","description":"","frontmatter":{"title":"焦面倾斜与场曲补偿","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/focus-tilt-compensation.md","filePath":"litho/focus-tilt-compensation.md","lastUpdated":1791413859000}'),p={name:"litho/focus-tilt-compensation.md"};function d(h,a,_,c,b,u){const s=B("Mermaid");return r(),m("div",null,[a[2]||(a[2]=i('<h1 id="焦面倾斜与场曲补偿" tabindex="-1">焦面倾斜与场曲补偿 <a class="header-anchor" href="#焦面倾斜与场曲补偿" aria-label="Permalink to &quot;焦面倾斜与场曲补偿&quot;">​</a></h1><div class="epigraph"><p>最佳焦面若在场上是斜的或弯的，调焦闭环对不准每一个场点；补偿是把可驱动的 $Z_4$ 与调平去贴那张面，不是改 NA。</p><footer>—— 场曲与倾斜的车间语言见 Malacara；光刻调平与离焦见 Levinson、Mack</footer></div><p><a href="/litho/aberration-nils-sensitivity">上一课</a>把 \\(c_j\\) 接到了 NILS。缺口是：视场上最佳焦面并不平——<strong>倾斜</strong>与<strong>场曲</strong>让狭缝两端和场角的有效离焦不同，敏感度再高也救不了没补偿的几何。本课钉这两项及其补偿，结束「成像的数学骨架」课序。二维孔与线端留给下一课序。不重推 \\(\\mathrm{DOF}=k_2\\lambda/\\mathrm{NA}^2\\) 的公式，只引用<a href="/litho/defocus-as-aberration">离焦作为像差</a>的 \\(Z_4\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>初级场曲（Petzval 一类）让离轴点的最佳焦面弯离近轴焦面；倾斜让整个焦面相对晶圆法向有一楔。扫描狭缝沿 \\(x\\) 瞬时曝光一条带，带上各点若 \\(c_4\\) 不同，NILS\\((z)\\) 的窗口对不齐，一层的公共焦窗按最差场点关死。调平传感器看到的是晶圆形貌，镜头场曲是光学面；两者差才是残差离焦。</p><p><span class="marginnote">直觉类比：把镜头想成一台投影仪，它的「清晰面」不是平的，而是一张微微翘起又弯曲的薯片面。晶圆只能放平，薯片面总有些位置对不准。倾斜是整张面翘了一头（楔），场曲是面本身弯了（碗）——两种毛病，两种补法。</span></p><p>缺口不是再写一次二次相位，而是：哪些项可以用工件台调平、扫描同步和镜头补偿吃掉，哪些必须当残差进预算。把场曲写成「晶圆不平」，会去拧涂胶；把晶圆翘曲写成「场曲」，会去拧镜头。</p><h3 id="倾斜不是远心" tabindex="-1">倾斜不是远心 <a class="header-anchor" href="#倾斜不是远心" aria-label="Permalink to &quot;倾斜不是远心&quot;">​</a></h3><p>远心误差是主光线斜率，造成套刻随离焦走，见主干远心课。焦面倾斜是 \\(z\\) 沿场线性变，造成 CD / NILS 沿场变。可以同时存在：一台机既可以远心残差，又可以焦面楔。敏感度上一课已经分开奇偶；本课的倾斜主要吃偶项里的有效 \\(z\\)。</p><p><span class="marginnote">扫描方向再平均一次：瞬时倾斜在狭缝宽度上积分。补偿表必须按狭缝坐标建，不能只用场中心的 Bossung。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：通过焦点的 CD 或 NILS 在狭缝若干点扫 \\(z\\)，拟合每点的最佳焦，得到一张 \\(z_\\mathrm{best}(x,y)\\)。分解成活塞（全局调焦）、倾斜（两轴楔）、弯曲（场曲残差）。晶圆形貌用调平光束另测，相减后才是光学场曲。</p><p><span class="marginnote">术语翻译：把 \\(z_\\mathrm{best}(x,y)\\) 这张「起伏的面」做三级分解——活塞是整面一起升降（全局调焦管它）；倾斜是面绕轴翘一头（调平或执行器管它）；场曲是剩下解不开的弯曲。就像处理一张皱纸：先整体平移、再整体旋转，剩下的褶皱才是真正的「皱」。</span></p><p>补偿：全局 \\(z\\) 跟活塞；工件台或镜头执行器跟楔；剩余弯曲进预算或靠镜头加热/补偿光学（公开可写的是「场相关调焦」，不写未公开行程）。浸没层水膜厚度误差也会冒充倾斜，要与光学项拆开。</p>',14)),(r(),l(n,null,{default:e(()=>[o(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22z_best%20%E5%9C%BA%E5%9B%BE%22%5D%20--%3E%20PIS%5B%22%E6%B4%BB%E5%A1%9E%20%E2%86%92%20%E8%B0%83%E7%84%A6%22%5D%0A%20%20MAP%20--%3E%20TIL%5B%22%E5%80%BE%E6%96%9C%20%E2%86%92%20%E8%B0%83%E5%B9%B3%20%2F%20%E6%89%A7%E8%A1%8C%E5%99%A8%22%5D%0A%20%20MAP%20--%3E%20CURV%5B%22%E5%9C%BA%E6%9B%B2%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20WAF%5B%22%E6%99%B6%E5%9C%86%E5%BD%A2%E8%B2%8C%22%5D%20--%3E%20LEV%5B%22%E8%B0%83%E5%B9%B3%22%5D%0A%20%20CURV%20--%3E%20BUD%5B%22%E7%84%A6%E7%AA%97%E9%A2%84%E7%AE%97%22%5D%0A%20%20LEV%20--%3E%20BUD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h3",{id:"与畸变、像散的协作",tabindex:"-1"},[E("与畸变、像散的协作 "),t("a",{class:"header-anchor",href:"#与畸变、像散的协作","aria-label":'Permalink to "与畸变、像散的协作"'},"​")],-1)),a[4]||(a[4]=t("p",null,"像散把 H/V 最佳焦劈开，场曲对两种取向不是同一张面。补偿若只贴一种取向的 \\(z_\\mathrm{best}\\)，另一种的 NILS 会掉——上一课敏感度在这里变成场上的取向冲突。畸变是横向位移，不靠调焦消除；不要把网格校正和焦面补偿写成一个环。",-1)),a[5]||(a[5]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=t("p",null,"每个场点的有效离焦 \\(z-z_\\mathrm{best}\\) 乘上一课的 \\(\\partial\\mathrm{NILS}/\\partial z\\)（即对 \\(c_4\\) 的敏感度），得到场上 NILS 地图。公共工艺窗是地图的交集。补偿降低的是这张地图的峰峰值，不是改变 \\(\\mathrm{NA}\\)。扫描同步若在狭缝方向留下动态倾斜，等效于补偿环没跟上的楔，CD 沿扫描向拖尾。",-1)),(r(),l(n,null,{default:e(()=>[o(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E8%A1%A5%E5%81%BF%E6%89%A7%E8%A1%8C%E5%99%A8%EF%BC%9A%E5%85%A8%E5%B1%80%20z%20%E4%B8%8E%E6%A5%94%22%5D%20--%3E%20RES%5B%22%E5%89%A9%E4%BD%99%E6%9C%89%E6%95%88%E7%A6%BB%E7%84%A6%20z%20%E5%87%8F%20z_best%22%5D%0A%20%20RES%20--%3E%20SENS%5B%22%E9%80%90%E7%82%B9%E4%B9%98%E7%A6%BB%E7%84%A6%E6%95%8F%E6%84%9F%E5%BA%A6%22%5D%0A%20%20SENS%20--%3E%20NMAP%5B%22%E5%9C%BA%E4%B8%8A%20NILS%20%E5%9C%B0%E5%9B%BE%22%5D%0A%20%20NMAP%20--%3E%20INTER%5B%22%E5%90%84%E5%9C%BA%E7%82%B9%E7%AA%97%E5%8F%A3%E5%8F%96%E4%BA%A4%E9%9B%86%22%5D%0A%20%20WORST%5B%22%E6%9C%80%E5%B7%AE%E5%9C%BA%E7%82%B9%22%5D%20--%3E%20INTER%0A%20%20INTER%20--%3E%20CW%5B%22%E5%85%AC%E5%85%B1%E7%84%A6%E7%AA%97%E5%AE%BD%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>这张图回答的问题是：「公共焦窗按最差点关死」是怎么算出来的。补偿先压低 \\(z_\\mathrm{best}\\) 的峰峰值，剩下的离焦逐点乘敏感度得到 NILS 地图，各点窗口取交集后，交集宽度由最差场点说了算。</p><p><span class="marginnote">数字实例：设焦深预算 100 nm，狭缝两端 \\(z_\\mathrm{best}\\) 分别为 +40 与 -40 nm（80 nm 峰峰的楔）。不补楔时，焦点只能取在中点，两端各离自己的最佳焦 40 nm，公共窗只剩 \\(100-80=20\\) nm，被砍掉八成；把楔补掉后全场剩余只剩几 nm，公共窗才接近单点窗。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写未公开的调平激光路数或镜头补偿器规格。EUV 反射系统同样有场曲，只是光路折叠不同，定义仍是 \\(z_\\mathrm{best}\\) 面。胶厚与薄膜摆动也会让「最佳焦」随栈变，那是下一单元的反射问题，不要在本课用 BARC 冒充场曲补偿。</p><p>至此，傅里叶对 → 采样 → PSF → 传递函数 → 判据 → Abbe/Hopkins → SOCS → 相干 → speckle → 矢量 → 像差敏感度 → 场焦补偿，骨架课序结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>场曲与倾斜使 \\(z_\\mathrm{best}\\) 随场变，公共焦窗按最差点关。</li><li>形貌归调平，光学面归镜头/执行器，残差进预算。</li><li>倾斜不是远心；像散让 H/V 焦面分裂。</li><li>补偿贴的是 NILS 地图的平坦度，不改截止频率。</li><li>下一课序：把骨架用到接触孔与线端。</li><li>出处：Malacara；Levinson；Mack；离焦 \\(Z_4\\) 见主干离焦课。</li></ul>',7))])}const S=A(p,[["render",d]]);export{C as __pageData,S as default};
